/**
 * Palace of Fine Arts, main floor, as laid out for Cal Hacks 13.0.
 *
 * Measured from the event's published floor plan (2000 × 1003 px image): tables, sponsor pins and
 * place pins were found by color, so their positions are exact to the plan; walls, rooms and
 * blocked areas are traced by hand. Coordinates stay in plan pixels so the plan can be corrected
 * in place; the 3D view converts them with PX_PER_M (Breakout #7's 54 ft side and the 6 ft table
 * spacing both give about 4.3 px per foot).
 *
 * Sponsor names come from the organizers' own 3D map and are filled in only where the label
 * clearly matched a pin; the rest show as "Sponsor table" until the official list is added.
 * The mezzanine (Mezzanine #2–#4, M5–M8, 41 more hacker tables) is not modeled yet.
 */
export type Pt = [number, number];

export const PX_PER_M = 14.1;
/**
 * Center of the hall's curve, and the radii of its inner (south) and outer (north) walls, in plan px:
 * circles fitted to the plan's walls, the south one set just outside the booths that stand against it.
 */
export const ARC = { center: [728, 1622] as Pt, inner: 1206, outer: 1612 };

